$page = is_array($page ?? null) ? $page : ['items' => [], 'total' => 0, 'page' => 1, 'pages' => 1];
$url = static fn(int $number): string => '/developer/academic-review?' . http_build_query(array_filter($filters + ['page_num' => $number], static fn(mixed $value): bool => is_scalar($value) && (string) $value !== ''));
