<section class="card pilot-progress" aria-labelledby="pilot-progress-heading"><h2 id="pilot-progress-heading">20-item academic pilot · your authorized scope</h2><p><?= (int) $pilotSummary['visible_in_scope'] ?> of 20 pilot items are visible in this account’s active board/subject grants. <?= (int) $pilotSummary['assigned_to_me'] ?> are assigned to you; <?= (int) $pilotSummary['decisions_recorded'] ?> have a recorded academic decision.</p><div class="pilot-progress-bar" role="progressbar" aria-label="Pilot items with an academic decision" aria-valuemin="0" aria-valuemax="<?= max(1, (int) $pilotSummary['visible_in_scope']) ?>" aria-valuenow="<?= (int) $pilotSummary['decisions_recorded'] ?>"><span style="width:<?= $pilotSummary['visible_in_scope'] > 0 ? min(100, (int) round(100 * $pilotSummary['decisions_recorded'] / $pilotSummary['visible_in_scope'])) : 0 ?>%"></span></div><ul class="pilot-progress-facts"><li><?= (int) ($pilotSummary['source_reviews_pending'] ?? 0) ?> source reviews pending</li><li><?= (int) ($pilotSummary['taxonomy_adjudications_pending'] ?? 0) ?> taxonomy decisions pending</li><li><?= (int) ($pilotSummary['study_adjudications_pending'] ?? 0) ?> study-link decisions pending</li></ul><p><small>These are separate gates. A source or academic decision is never inferred from a URL, assignment, or pilot selection.</small></p></section>
<form class="filter-bar academic-review-filter" method="get" action="/developer/academic-review">
    <div class="review-filter-field"><label for="review-search">Search proposal ID or question text</label><input id="review-search" class="field-control" type="search" name="search" value="<?= $escape($filters['search'] ?? '') ?>"></div>
    <div class="review-filter-field"><label for="review-board">Board</label><select id="review-board" class="field-control" name="board"><option value="">All authorized boards</option><?php foreach ($boards as $id): ?><option value="<?= $escape($id) ?>"<?= ($filters['board'] ?? '') === $id ? ' selected' : '' ?>><?= $escape($id) ?></option><?php endforeach; ?></select></div>
    <div class="review-filter-field"><label for="review-subject">Subject</label><select id="review-subject" class="field-control" name="subject"><option value="">All authorized subjects</option><?php foreach ($subjects as $id): ?><option value="<?= $escape($id) ?>"<?= ($filters['subject'] ?? '') === $id ? ' selected' : '' ?>><?= $escape($id) ?></option><?php endforeach; ?></select></div>
    <div class="review-filter-field"><label for="review-status">Academic status</label><select id="review-status" class="field-control" name="status"><option value="">All states</option><?php foreach (['PENDING_REVIEW','ASSIGNED','IN_REVIEW','REVISION_REQUESTED','APPROVED','REJECTED','DEFERRED'] as $state): ?><option value="<?= $state ?>"<?= strtoupper((string) ($filters['status'] ?? '')) === $state ? ' selected' : '' ?>><?= str_replace('_', ' ', $state) ?></option><?php endforeach; ?></select></div>
    <div class="review-filter-field"><label for="review-assigned">Assignment</label><select id="review-assigned" class="field-control" name="assigned"><option value="">Any assignment</option><option value="mine"<?= ($filters['assigned'] ?? '') === 'mine' ? ' selected' : '' ?>>Assigned to me</option><option value="unassigned"<?= ($filters['assigned'] ?? '') === 'unassigned' ? ' selected' : '' ?>>Unassigned</option></select></div>
    <div class="review-filter-field"><label for="review-pilot">Cohort</label><select id="review-pilot" class="field-control" name="pilot"><option value="">All B695 proposals</option><option value="1"<?= ($filters['pilot'] ?? '') === '1' ? ' selected' : '' ?>>Batch 715 pilot only</option></select></div>
    <button type="submit">Apply filters</button>
