<?php foreach ($page['items'] as $row): $proposal = (array) ($row['proposal'] ?? []); $workflow = (array) ($row['workflow'] ?? []); $question = (array) ($proposal['proposed_question'] ?? []); $pilotItem = \App\Services\Question\Batch715AcademicPilotService::find((string) ($proposal['question_id'] ?? '')); $pilotReadiness = $pilotItem === null ? null : \App\Services\Question\Batch715AcademicPilotService::evidence((string) ($proposal['question_id'] ?? '')); $sources = is_array($pilotReadiness['sources'] ?? null) ? $pilotReadiness['sources'] : []; $examinedCount = count(array_filter($sources, static fn(array $source): bool => !empty($source['content_examined']))); ?>
